/**
 * @param {string} s
 * @return {boolean}
 */
var checkOnesSegment = function(s) {
    let started = false;
    let ended = false;

    for (const char of s) {
        if (char === '0') {
            if (started && !ended) {
                ended = true;
            }
            continue;
        }

        if (ended) {
            return false;
        }

        if (!started) {
            started = true;
        }
    }

    return true;
};

/**
 * @param {string} s
 * @return {boolean}
 */
var checkOnesSegment = function(s) {
    let lastOne = -1;

    for (let i = 0; i < s.length; i++) {
        if (s[i] === '1') {
            if (lastOne > -1 && i - lastOne > 1) {
                return false;
            }
            lastOne = i;
        }
    }

    return true;
};
